    "title": "גלבוע ועמק חרוד: מגידו–הר שאול–בית שאן",
    "region": "צפון",
    "area": "עמקים וגלבוע",
    "level": "קל–בינוני",
    "road_character": "מפותל מאוד",
    "start": "צומת מגידו",
