    "title": "מקורות הירקון ואנטיפטריס: ראש העין–אפולוניה הפנימית–מגדל צדק–נאות קדומים",
    "region": "מרכז",
    "area": "ראש העין, השפלה הצפונית ומודיעין",
    "level": "קל",
    "road_character": "כבישים אזוריים שקטים",
    "start": "ראש העין",
