    "title": "נחל צלמון וטחנות הגליל: כרמיאל–פרוד–צלמון–מג׳אר–טבריה",
    "region": "צפון",
    "area": "גליל תחתון ומזרחי",
    "level": "בינוני",
    "road_character": "מפותל בינוני",
    "start": "כרמיאל",
